SET ANSI_NULLS ON;SET QUOTED_IDENTIFIER ON;SET ANSI_PADDING ON;SET ANSI_WARNINGS ON;SET ARITHABORT ON;SET CONCAT_NULL_YIELDS_NULL ON;SET NUMERIC_ROUNDABORT OFF;
DECLARE @schema sysname,@table sysname,@column sysname,@sql nvarchar(max),@index sysname;
DECLARE fk CURSOR LOCAL FAST_FORWARD FOR SELECT DISTINCT OBJECT_SCHEMA_NAME(fkc.parent_object_id),OBJECT_NAME(fkc.parent_object_id),COL_NAME(fkc.parent_object_id,fkc.parent_column_id) FROM sys.foreign_keys k JOIN sys.foreign_key_columns fkc ON fkc.constraint_object_id=k.object_id WHERE k.is_disabled=0 AND NOT EXISTS(SELECT 1 FROM sys.index_columns ic WHERE ic.object_id=fkc.parent_object_id AND ic.column_id=fkc.parent_column_id AND ic.key_ordinal=1);
OPEN fk;FETCH NEXT FROM fk INTO @schema,@table,@column;WHILE @@FETCH_STATUS=0 BEGIN SET @index=LEFT('IX_'+@table+'_'+@column,128);SET @sql=N'CREATE INDEX '+QUOTENAME(@index)+N' ON '+QUOTENAME(@schema)+N'.'+QUOTENAME(@table)+N'('+QUOTENAME(@column)+N')';BEGIN TRY EXEC sp_executesql @sql;END TRY BEGIN CATCH IF ERROR_NUMBER() NOT IN(1913,2714) THROW;END CATCH;FETCH NEXT FROM fk INTO @schema,@table,@column;END;CLOSE fk;DEALLOCATE fk;
